package com.acid.camera;
import android.content.Context;import android.graphics.*;import android.opengl.*;import java.nio.*;import java.util.*;
/** Original GLES2 three-pass pipeline. Camera readback/upload is currently CPU-mediated. */
class ShaderEngine {
 private static EGLDisplay sharedDisplay;private static int displayUsers;
 static synchronized EGLDisplay acquireDisplay(){if(displayUsers==0){sharedDisplay=EGL14.eglGetDisplay(EGL14.EGL_DEFAULT_DISPLAY);int[] v=new int[2];if(!EGL14.eglInitialize(sharedDisplay,v,0,v,1))throw new IllegalStateException("EGL initialization failed");}displayUsers++;return sharedDisplay;}
 static synchronized void releaseDisplay(){if(displayUsers>0&&--displayUsers==0){EGL14.eglTerminate(sharedDisplay);sharedDisplay=null;}}

 EGLDisplay display;EGLContext context;EGLSurface surface;int input,framebuffer;int[] ping=new int[2],history=new int[3];int[] oldIds={-1,-1,-1};boolean[] valid=new boolean[3];int width,height;final String vertex,fragment;Map<Integer,Integer> programs=new HashMap<>();FloatBuffer quad;long previous=System.nanoTime();String renderer;
 ShaderEngine(Context c,SurfaceTexture window)throws Exception{
 vertex=FxCatalog.read(c,"fx/vertex.glsl");fragment=FxCatalog.read(c,"fx/effect.glsl");try{display=acquireDisplay();int[] configAttrs={EGL14.EGL_RENDERABLE_TYPE,EGL14.EGL_OPENGL_ES2_BIT,EGL14.EGL_SURFACE_TYPE,EGL14.EGL_WINDOW_BIT|EGL14.EGL_PBUFFER_BIT,EGL14.EGL_RED_SIZE,8,EGL14.EGL_GREEN_SIZE,8,EGL14.EGL_BLUE_SIZE,8,EGL14.EGL_ALPHA_SIZE,8,EGL14.EGL_NONE};EGLConfig[] configs=new EGLConfig[1];int[] count=new int[1];if(!EGL14.eglChooseConfig(display,configAttrs,0,configs,0,1,count,0)||count[0]==0)throw new Exception("No GLES2 surface config");context=EGL14.eglCreateContext(display,configs[0],EGL14.EGL_NO_CONTEXT,new int[]{EGL14.EGL_CONTEXT_CLIENT_VERSION,2,EGL14.EGL_NONE},0);surface=window==null?EGL14.eglCreatePbufferSurface(display,configs[0],new int[]{EGL14.EGL_WIDTH,1,EGL14.EGL_HEIGHT,1,EGL14.EGL_NONE},0):EGL14.eglCreateWindowSurface(display,configs[0],window,new int[]{EGL14.EGL_NONE},0);if(!EGL14.eglMakeCurrent(display,surface,surface,context))throw new Exception("EGL makeCurrent failed");renderer=GLES20.glGetString(GLES20.GL_RENDERER)+" / "+GLES20.glGetString(GLES20.GL_VERSION);quad=ByteBuffer.allocateDirect(8*4).order(ByteOrder.nativeOrder()).asFloatBuffer();quad.put(new float[]{-1,-1,1,-1,-1,1,1,1}).position(0);int[] f={0};GLES20.glGenFramebuffers(1,f,0);framebuffer=f[0];input=texture();program(0); }catch(Exception|Error e){release();throw e;}
 }
 int texture(){int[] a={0};GLES20.glGenTextures(1,a,0);GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,a[0]);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MIN_FILTER,GLES20.GL_LINEAR);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_MAG_FILTER,GLES20.GL_LINEAR);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_WRAP_S,GLES20.GL_CLAMP_TO_EDGE);GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D,GLES20.GL_TEXTURE_WRAP_T,GLES20.GL_CLAMP_TO_EDGE);return a[0];}
 void storage(int tex,int w,int h){GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,tex);GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D,0,GLES20.GL_RGBA,w,h,0,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,null);}
 void allocate(int w,int h){if(w==width&&h==height)return;int[] max={0};GLES20.glGetIntegerv(GLES20.GL_MAX_TEXTURE_SIZE,max,0);if(w>max[0]||h>max[0])throw new IllegalStateException("Image exceeds GPU texture limit "+max[0]);width=w;height=h;for(int i=0;i<2;i++){if(ping[i]==0)ping[i]=texture();storage(ping[i],w,h);}for(int i=0;i<3;i++){if(history[i]!=0){GLES20.glDeleteTextures(1,history,i);history[i]=0;}valid[i]=false;oldIds[i]=-1;}}
 int shader(int type,String source){int s=GLES20.glCreateShader(type);GLES20.glShaderSource(s,source);GLES20.glCompileShader(s);int[] ok={0};GLES20.glGetShaderiv(s,GLES20.GL_COMPILE_STATUS,ok,0);if(ok[0]==0){String log=GLES20.glGetShaderInfoLog(s);GLES20.glDeleteShader(s);throw new IllegalStateException("Shader: "+log);}return s;}
 int program(int id){Integer old=programs.get(id);if(old!=null)return old;int v=shader(GLES20.GL_VERTEX_SHADER,vertex),f=shader(GLES20.GL_FRAGMENT_SHADER,"#define FX "+id+"\n"+fragment);int p=GLES20.glCreateProgram();GLES20.glAttachShader(p,v);GLES20.glAttachShader(p,f);GLES20.glLinkProgram(p);GLES20.glDeleteShader(v);GLES20.glDeleteShader(f);int[] ok={0};GLES20.glGetProgramiv(p,GLES20.GL_LINK_STATUS,ok,0);if(ok[0]==0)throw new IllegalStateException(GLES20.glGetProgramInfoLog(p));programs.put(id,p);return p;}
 void uniform(int p,String name,float value){GLES20.glUniform1f(GLES20.glGetUniformLocation(p,name),value);}
 void draw(int source,int dest,int w,int h,int effect,FxState.Slot slot,int historyTex,boolean hasHistory,boolean flip,float dt){GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,dest==0?0:framebuffer);if(dest!=0){GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,dest,0);if(GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER)!=GLES20.GL_FRAMEBUFFER_COMPLETE)throw new IllegalStateException("GPU framebuffer unavailable");}GLES20.glViewport(0,0,w,h);int p=program(effect);GLES20.glUseProgram(p);int position=GLES20.glGetAttribLocation(p,"aPosition");GLES20.glEnableVertexAttribArray(position);quad.position(0);GLES20.glVertexAttribPointer(position,2,GLES20.GL_FLOAT,false,0,quad);GLES20.glActiveTexture(GLES20.GL_TEXTURE0);GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,source);GLES20.glUniform1i(GLES20.glGetUniformLocation(p,"uImage"),0);GLES20.glActiveTexture(GLES20.GL_TEXTURE1);GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,historyTex==0?source:historyTex);GLES20.glUniform1i(GLES20.glGetUniformLocation(p,"uHistory"),1);GLES20.glUniform2f(GLES20.glGetUniformLocation(p,"uSize"),width,height);GLES20.glUniform3f(GLES20.glGetUniformLocation(p,"uP"),slot.p[0],slot.p[1],slot.p[2]);uniform(p,"uMix",slot.mix);uniform(p,"uTime",(System.nanoTime()/1000000L%3600000)/1000f);uniform(p,"uDt",dt);uniform(p,"uHasHistory",hasHistory?1:0);uniform(p,"uFlip",flip?1:0);GLES20.glDrawArrays(GLES20.GL_TRIANGLE_STRIP,0,4);GLES20.glDisableVertexAttribArray(position);int error=GLES20.glGetError();if(error!=GLES20.GL_NO_ERROR)throw new IllegalStateException("GL error "+error);}
 int render(Bitmap b,FxState state){allocate(b.getWidth(),b.getHeight());GLES20.glActiveTexture(GLES20.GL_TEXTURE0);GLES20.glBindTexture(GLES20.GL_TEXTURE_2D,input);GLUtils.texImage2D(GLES20.GL_TEXTURE_2D,0,b,0);long now=System.nanoTime();float dt=Math.min(.5f,(now-previous)/1e9f);previous=now;FxState.Slot identity=new FxState.Slot();draw(input,ping[0],width,height,0,identity,0,false,true,dt);int current=0;for(int i=0;i<3;i++){FxState.Slot s=state.slots[i];if(state.bypass||!s.enabled||s.id==0||s.mix==0){valid[i]=false;continue;}if(oldIds[i]!=s.id){for(int j=i;j<3;j++)valid[j]=false;oldIds[i]=s.id;}boolean temporal=s.id>=50;if(temporal&&history[i]==0){history[i]=texture();storage(history[i],width,height);valid[i]=false;}int next=1-current;draw(ping[current],ping[next],width,height,s.id,s,history[i],valid[i],false,dt);if(temporal){draw(s.id==50?ping[current]:ping[next],history[i],width,height,0,identity,0,false,false,dt);valid[i]=true;}current=next;}return ping[current];}
 void show(int tex,int w,int h){draw(tex,0,w,h,0,new FxState.Slot(),0,false,false,0);if(!EGL14.eglSwapBuffers(display,surface))throw new IllegalStateException("EGL swap failed");}
 Bitmap read(int tex){GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER,framebuffer);GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER,GLES20.GL_COLOR_ATTACHMENT0,GLES20.GL_TEXTURE_2D,tex,0);ByteBuffer bytes=ByteBuffer.allocateDirect(width*height*4);GLES20.glReadPixels(0,0,width,height,GLES20.GL_RGBA,GLES20.GL_UNSIGNED_BYTE,bytes);int[] pixels=new int[width*height];for(int y=0;y<height;y++)for(int x=0;x<width;x++){int offset=((height-1-y)*width+x)*4;pixels[y*width+x]=0xff000000|((bytes.get(offset)&255)<<16)|((bytes.get(offset+1)&255)<<8)|(bytes.get(offset+2)&255);}return Bitmap.createBitmap(pixels,width,height,Bitmap.Config.ARGB_8888);}
 void resetHistory(){Arrays.fill(valid,false);}
 void release(){if(display==null)return;try{if(context!=null&&surface!=null)EGL14.eglMakeCurrent(display,surface,surface,context);for(int p:programs.values())GLES20.glDeleteProgram(p);GLES20.glDeleteTextures(1,new int[]{input},0);GLES20.glDeleteTextures(2,ping,0);GLES20.glDeleteTextures(3,history,0);GLES20.glDeleteFramebuffers(1,new int[]{framebuffer},0);EGL14.eglMakeCurrent(display,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_SURFACE,EGL14.EGL_NO_CONTEXT);if(surface!=null)EGL14.eglDestroySurface(display,surface);if(context!=null)EGL14.eglDestroyContext(display,context);releaseDisplay();EGL14.eglReleaseThread();}catch(Exception ignored){}display=null;}
}
